# Function-level text check (no compile). Every function of the musttail variant should equal the
# same function of a flag-off variant (build/agent9/generated/<Off>, default off3) with each plain tail
# call rewritten exactly as emit_tail_call / emit_tail_call_line print it. Works across a different TU
# partition. Also counts the sites. -> textcheck_<Off>.txt
# NOTE: musttail was generated by the 21:08 exe (A8036AC8947D70BA, per Agent 9: gen-steps.txt shows
# 565FDE81CFEA7B4A because gen.ps1 hashed the exe before its 881 s slot wait); off by 565FDE81CFEA7B4A
# (19:19, no SO fold), off2 by E35C3D09AB3DA2B6 (21:28), off3 by EEBB5406CF78E392 (21:52). A function
# can therefore also differ for reasons that have nothing to do with tail calls; those are split out
# by comparing the per-function musttail-site counts.
#   powershell -NoProfile -File bench/agent9/musttail/textcheck.ps1 [-Off off3]   (one step; run it in one slot)
param([string]$Off = 'off3')
$ErrorActionPreference = 'Stop'
$offName = $Off   # PowerShell names are case-insensitive: $off below is the same variable as $Off
$root = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'))
$var = Join-Path $root 'build/agent9/generated/musttail/default'
$off = Join-Path $root "build/agent9/generated/$offName/default"
$offSha = (@(Get-Content (Join-Path $root 'build/agent9/logs/gen-steps.txt') | Where-Object { $_ -match ('\[' + [regex]::Escape($offName) + '\] BEGIN .*sha=(\w+)') } | ForEach-Object { $Matches[1] }) | Select-Object -Last 1)
$reU = [regex]'(?m)^\t([A-Za-z_][A-Za-z0-9_]*)\(ctx, base\);\r?\n\treturn;'
$reC = [regex]'(?m)^\t\t([A-Za-z_][A-Za-z0-9_]*)\(ctx, base\);\r?\n\t\treturn;'
$reFn = [regex]'(?m)^DEFINE_REX_FUNC\((\w+)\)'
$reMt = [regex]'\[\[clang::musttail\]\]'
$sha = [Security.Cryptography.SHA1]::Create()
$enc = [Text.Encoding]::UTF8
# map: function name -> "sha1|musttail sites in the function"
function Add-Fns([string]$s, [hashtable]$map) {
  $ms = $reFn.Matches($s)
  for ($i = 0; $i -lt $ms.Count; $i++) {
    $start = $ms[$i].Index
    $end = if ($i + 1 -lt $ms.Count) { $ms[$i + 1].Index } else { $s.Length }
    $body = $s.Substring($start, $end - $start)
    $map[$ms[$i].Groups[1].Value] = [Convert]::ToBase64String($sha.ComputeHash($enc.GetBytes($body))) + '|' + $reMt.Matches($body).Count
  }
}
$sw = [Diagnostics.Stopwatch]::StartNew()
$mt = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
$mtSites = 0; $mtPlainLeft = 0; $mtFiles = 0
foreach ($f in Get-ChildItem $var -Filter 'legodimensions_recomp.*.cpp') {
  $s = [IO.File]::ReadAllText($f.FullName); $mtFiles++
  $mtSites += $reMt.Matches($s).Count
  $mtPlainLeft += $reU.Matches($s).Count + $reC.Matches($s).Count
  Add-Fns $s $mt
}
$of = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
$offU = 0; $offC = 0; $offFiles = 0
foreach ($f in Get-ChildItem $off -Filter 'legodimensions_recomp.*.cpp') {
  $s = [IO.File]::ReadAllText($f.FullName); $offFiles++
  $offU += $reU.Matches($s).Count; $offC += $reC.Matches($s).Count
  $t = $reC.Replace($reU.Replace($s, "`t[[clang::musttail]] return `$1(ctx, base);"), "`t`t[[clang::musttail]] return `$1(ctx, base);")
  Add-Fns $t $of
}
$same = 0; $onlyOff = 0; $diffSameSites = New-Object System.Collections.Generic.List[string]; $diffSites = New-Object System.Collections.Generic.List[string]
$sitesCommonMt = 0; $sitesCommonOff = 0
foreach ($k in $of.Keys) {
  if (-not $mt.ContainsKey($k)) { $onlyOff++; continue }
  $a = $mt[$k]; $b = $of[$k]
  $sitesCommonMt += [int]($a -replace '^.*\|', ''); $sitesCommonOff += [int]($b -replace '^.*\|', '')
  if ($a -ceq $b) { $same++ }
  elseif (($a -replace '^.*\|', '') -eq ($b -replace '^.*\|', '')) { $diffSameSites.Add($k) }
  else { $diffSites.Add($k) }
}
$onlyMt = 0; foreach ($k in $mt.Keys) { if (-not $of.ContainsKey($k)) { $onlyMt++ } }
$lines = @(
  "musttail variant: $var (21:08 exe A8036AC8947D70BA)",
  "flag-off variant: $off (exe $offSha, from build/agent9/logs/gen-steps.txt)",
  "recomp TUs: musttail $mtFiles, off $offFiles",
  "functions: musttail $($mt.Count), off $($of.Count); only in off $onlyOff, only in musttail $onlyMt",
  "plain tail sites in off: $offU unconditional + $offC conditional/jump-table = $($offU + $offC)",
  "[[clang::musttail]] sites in musttail: $mtSites; plain tail-call text left in musttail: $mtPlainLeft",
  "common functions: musttail sites $sitesCommonMt (musttail variant) vs $sitesCommonOff (rewritten off)",
  "common functions identical to the rewritten flag-off text: $same; different text but the same musttail-site count: $($diffSameSites.Count); different musttail-site count: $($diffSites.Count)"
)
if ($diffSites.Count) { $lines += 'functions whose musttail-site count differs (first 20): ' + (($diffSites | Select-Object -First 20) -join ', ') }
if ($diffSameSites.Count) { $lines += 'functions with other text differences (first 20): ' + (($diffSameSites | Select-Object -First 20) -join ', ') }
$o = foreach ($n in 'legodimensions_register.cpp', 'legodimensions_init.cpp', 'legodimensions_init.h', 'legodimensions_pch.h') {
  $a = Join-Path $var $n; $b = Join-Path $off $n
  if ((Test-Path $a) -and (Test-Path $b)) { "$n identical: $((Get-FileHash $a).Hash -eq (Get-FileHash $b).Hash)" } else { "$n missing" }
}
$lines += $o
$lines += "time: $([math]::Round($sw.Elapsed.TotalSeconds, 1)) s"
$lines | Tee-Object -FilePath (Join-Path $PSScriptRoot "textcheck_$offName.txt")
